{koyu:n = N / N{alt:A}}  |  {koyu:n = m / M{alt:A}}  |  {koyu:n = V{alt:NK} / 22,4}  |  {koyu:n = V{alt:OK} / 24,5}
• {koyu:1 gram = N{alt:A} akb}
• {koyu:Atom Mol Sayısı = Bileşik Molü x Birim Formüldeki Atom Sayısı}
